package com.ureclive.urec_live_backend.dto;

import com.ureclive.urec_live_backend.entity.MessageKind;

/**
 * STOMP payload for /app/chat.community.send and /app/chat.dm.send. Validated by ChatMessageService,
 * which reports problems on the sender's /user/queue/errors with the same clientId.
 */
public class SendChatMessageRequest {

    public static final int MAX_CONTENT_LENGTH = 500;
    public static final int MAX_CLIENT_ID_LENGTH = 36;

    /** Generated by the app per message; lets it match the echo and retry without duplicates. */
    private String clientId;

    /** DMs only. */
    private String recipient;

    /** Required for TEXT; ignored for GIF and STICKER. */
    private String content;

    /** Defaults to TEXT, so older apps that send only {content} keep working. */
    private MessageKind kind;

    /** Required for GIF and STICKER. */
    private MediaPayload media;

    public static class MediaPayload {
        private String url;
        private String previewUrl;
        private Integer width;
        private Integer height;
        private String providerId;

        public MediaPayload() {}

        public MediaPayload(String url, String previewUrl, Integer width, Integer height, String providerId) {
            this.url = url;
            this.previewUrl = previewUrl;
            this.width = width;
            this.height = height;
            this.providerId = providerId;
        }

        public String getUrl() { return url; }
        public void setUrl(String url) { this.url = url; }
        public String getPreviewUrl() { return previewUrl; }
        public void setPreviewUrl(String previewUrl) { this.previewUrl = previewUrl; }
        public Integer getWidth() { return width; }
        public void setWidth(Integer width) { this.width = width; }
        public Integer getHeight() { return height; }
        public void setHeight(Integer height) { this.height = height; }
        public String getProviderId() { return providerId; }
        public void setProviderId(String providerId) { this.providerId = providerId; }
    }

    public String getClientId() { return clientId; }
    public void setClientId(String clientId) { this.clientId = clientId; }
    public String getRecipient() { return recipient; }
    public void setRecipient(String recipient) { this.recipient = recipient; }
    public String getContent() { return content; }
    public void setContent(String content) { this.content = content; }
    public MessageKind getKind() { return kind == null ? MessageKind.TEXT : kind; }
    public void setKind(MessageKind kind) { this.kind = kind; }
    public MediaPayload getMedia() { return media; }
    public void setMedia(MediaPayload media) { this.media = media; }
}
